<span class="line"><span style="color:#C678DD;">    for</span><span style="color:#ABB2BF;"> i, sales </span><span style="color:#C678DD;">in</span><span style="color:#56B6C2;"> enumerate</span><span style="color:#ABB2BF;">(similar_sales_data):</span></span>
